                // Selection can sometimes be out of sync with the view during rapid changes
                if (from < 0 || to > editor.state.doc.content.size) {
                    setBubbleMenu({ isOpen: false, top: 0, left: 0 });
                    return;
                }

                if (!empty && (to - from) < 5000) {
                    // VERIFY VIEW: Ensure the editor view is ready and not destroyed
                    if (!editor.view || !editor.view.domAtPos) {
                        setBubbleMenu({ isOpen: false, top: 0, left: 0 });
                        return;
                    }

                    // DEEP SAFETY: Check if the position exists in the current view mapping
                    try {
                        const { node } = editor.view.domAtPos(from);
                        if (!node) {
                            setBubbleMenu({ isOpen: false, top: 0, left: 0 });
                            return;
                        }

                        // Use native DOM selection for accurate bounding box
                        const domSelection = window.getSelection();
                        if (domSelection.rangeCount > 0) {
                            const range = domSelection.getRangeAt(0);
                            const rect = range.getBoundingClientRect();

                            // Estimate menu width to center it (approx 280px wide)
                            const estimatedMenuWidth = 280;
                            // Calculate ideal left center
                            let computedLeft = rect.left + (rect.width / 2) - (estimatedMenuWidth / 2);

                            // Clamp to screen edges
                            const maxLeft = window.innerWidth - estimatedMenuWidth - 20;
                            computedLeft = Math.max(20, Math.min(computedLeft, maxLeft));

                            setBubbleMenu({
                                isOpen: true,
                                top: Math.max(10, rect.top - 50),
                                left: computedLeft
                            });
                            setSlashMenu(prev => ({ ...prev, isOpen: false }));
                        } else {
                            setBubbleMenu({ isOpen: false, top: 0, left: 0 });
                        }
                    } catch (innerErr) {
                        // This handles cases where domAtPos or coordsAtPos throws
                        setBubbleMenu({ isOpen: false, top: 0, left: 0 });
                    }
                } else {
                    setBubbleMenu({ isOpen: false, top: 0, left: 0 });

                    if (empty) {
                        const $pos = editor.state.doc.resolve(from);
                        const parent = $pos.parent;
                        if (!parent) return;

                        // textBetween can throw if offsets are invalid
                        const textBefore = parent.textBetween(0, Math.min($pos.parentOffset, parent.content.size), '\n');
                        const slashMatch = textBefore.match(/(?:^|\s)\/([a-zA-Z0-9]*)$/);
                        const tagMatch = textBefore.match(/(?:^|\s)#([a-zA-Z0-9_-]*)$/);
                        const linkMatch = textBefore.match(/(?:^|\s)\[\[([a-zA-Z0-9_\-\s]*)$/);

                        if (slashMatch) {
                            const query = slashMatch[1];
                            const triggerIdx = from - query.length - 1;

                            try {
                                const coords = editor.view.coordsAtPos(triggerIdx);
                                if (coords && typeof coords.bottom === 'number' && typeof coords.left === 'number') {
                                    const menuHeight = 320;
                                    const viewportHeight = window.innerHeight;
                                    const wouldOverflow = coords.bottom + menuHeight > viewportHeight - 20;

                                    setSlashMenu({
                                        isOpen: true,
                                        top: wouldOverflow ? Math.max(10, coords.top - menuHeight - 10) : coords.bottom + 4,
                                        left: coords.left,
                                        query: query,
                                        triggerIdx: triggerIdx,
                                        selectedIndex: 0
                                    });
                                } else {
                                    setSlashMenu(prev => ({ ...prev, isOpen: false }));
                                }
                            } catch (e) {
                                setSlashMenu(prev => ({ ...prev, isOpen: false }));
                            }
                            setTagMenu(prev => ({ ...prev, isOpen: false }));
                            setLinkMenu(prev => ({ ...prev, isOpen: false }));
                        } else if (tagMatch) {
                            const query = tagMatch[1];
                            const triggerIdx = from - query.length - 1;

                            try {
                                const coords = editor.view.coordsAtPos(triggerIdx);
                                if (coords && typeof coords.bottom === 'number' && typeof coords.left === 'number') {
                                    const menuHeight = 200;
                                    const viewportHeight = window.innerHeight;
                                    const wouldOverflow = coords.bottom + menuHeight > viewportHeight - 20;

                                    setTagMenu({
                                        isOpen: true,
                                        top: wouldOverflow ? Math.max(10, coords.top - menuHeight - 10) : coords.bottom + 4,
                                        left: coords.left,
                                        query: query || '',
                                        triggerIdx: triggerIdx,
                                        selectedIndex: 0
                                    });
                                } else {
                                    setTagMenu(prev => ({ ...prev, isOpen: false }));
                                }
                            } catch (e) {
                                setTagMenu(prev => ({ ...prev, isOpen: false }));
                            }
                            setSlashMenu(prev => ({ ...prev, isOpen: false }));
                            setLinkMenu(prev => ({ ...prev, isOpen: false }));
                        } else if (linkMatch) {
                            const query = linkMatch[1];
                            const triggerIdx = from - query.length - 2; // -2 for '[['

                            try {
                                const coords = editor.view.coordsAtPos(triggerIdx);
                                if (coords && typeof coords.bottom === 'number' && typeof coords.left === 'number') {
                                    const menuHeight = 200;
                                    const viewportHeight = window.innerHeight;
                                    const wouldOverflow = coords.bottom + menuHeight > viewportHeight - 20;

                                    setLinkMenu({
                                        isOpen: true,
                                        top: wouldOverflow ? Math.max(10, coords.top - menuHeight - 10) : coords.bottom + 4,
                                        left: coords.left,
                                        query: query || '',
                                        triggerIdx: triggerIdx,
                                        selectedIndex: 0
                                    });
                                } else {
                                    setLinkMenu(prev => ({ ...prev, isOpen: false }));
                                }
                            } catch (e) {
                                setLinkMenu(prev => ({ ...prev, isOpen: false }));
                            }
                            setLinkMenu(prev => ({ ...prev, isOpen: false }));
                        }
                    } else if (event.key === 'Insert' && editor) {
                        event.preventDefault();
                        setIsTemplateModalOpen(true);
                        return true;
                    }
                }
            } catch (err) {
                console.error('Editor: Selection update error', err);
                setBubbleMenu({ isOpen: false, top: 0, left: 0 });
                setSlashMenu(prev => ({ ...prev, isOpen: false }));
            }
        },

        onBlur: () => {
            setBubbleMenu({ isOpen: false, top: 0, left: 0 });
            setSlashMenu(prev => ({ ...prev, isOpen: false }));
            setTagMenu(prev => ({ ...prev, isOpen: false }));
        }

    });

    const handleTitleChange = useCallback((e) => {
        const newName = e.target.value;
        setLocalTitle(newName);
        debouncedSave({ name: newName });
    }, [debouncedSave]);

    const handleKeyDown = useCallback((e) => {
        // Keyboard handling is now done inside editorProps.handleKeyDown
    }, []);

    useEffect(() => {
        if (slashMenu.isOpen && slashMenuListRef.current) {
            const activeItem = slashMenuListRef.current.children[slashMenu.selectedIndex];
            if (activeItem) {
                activeItem.scrollIntoView({ block: 'nearest' });
            }
        }
    }, [slashMenu.selectedIndex, slashMenu.isOpen]);

    useEffect(() => {
        if (tagMenu.isOpen && tagMenuListRef.current) {
            const activeItem = tagMenuListRef.current.children[tagMenu.selectedIndex];
            if (activeItem) {
                activeItem.scrollIntoView({ block: 'nearest' });
            }
        }
    }, [tagMenu.selectedIndex, tagMenu.isOpen]);

    useEffect(() => {
        if (linkMenu.isOpen && linkMenuListRef.current) {
            const activeItem = linkMenuListRef.current.children[linkMenu.selectedIndex];
            if (activeItem) {
                activeItem.scrollIntoView({ block: 'nearest' });
            }
        }
    }, [linkMenu.selectedIndex, linkMenu.isOpen]);

    useEffect(() => {
        const f = nodes.find(n => n.id === fileId);
        if (f) {
            const isInitialLoad = !file || file.id !== fileId;
            // Also force update if a sync occurred, OR if the file content explicitly diverged
            // from our locally typed buffered content.
            // ONLY DO THIS IF THE USER IS NOT ACTIVELY TYPING to prevent cursor jumps and deleted characters!
            const isExternalUpdate = !isInitialLoad && !isTypingRef.current && (
                syncPulse > 0 ||
                (f.content !== undefined &&
                    f.content !== (file?.content || '') &&
                    f.content !== lastSavedContentRef.current &&
                    f.updatedAt > (file?.updatedAt || 0))
            );

            // Keep file state up to date without necessarily re-loading editor
            setFile(f);

            if (isInitialLoad || isExternalUpdate) {
                if (isInitialLoad) {
                    setLocalTitle(f.name || '');
                    lastSavedContentRef.current = f.content || ''; // initialize ref
                }

                if (editor) {
                    const loadContent = async () => {
                        let content = f.content;
                        // On-demand loading OR force reload if external update
                        if (content === undefined || isExternalUpdate) {
                            try {
                                content = await getFileContent(fileId);
                                // Update local state so we don't fetch again
                                setFile(prev => prev?.id === fileId ? { ...prev, content } : prev);
                            } catch (err) {
                                console.error('[Editor] Failed to load file content:', err);
                                return;
                            }
                        }

                        lastSavedContentRef.current = content || '';

                        // Ensure task list markers have a space after them for markdown-it-task-lists
                        const preparedContent = (content || '').replace(/^(\s*-\s*\[[ xX]\])(\S)/gm, '$1 $2');
                        let html = md.render(preparedContent);

                        // Convert regular task lists to data-type="taskList" and items to taskItem
                        html = html.replace(/<ul[^>]*class=["'][^"']*task-list[^"']*["'][^>]*>/gi, '<ul data-type="taskList">')
                            .replace(/<li[^>]*class=["'][^"']*task-list-item[^"']*["'][^>]*>/gi, '<li data-type="taskItem">');

                        // Extract @date and move to attribute, but keep other content clean
                        html = html.replace(/(<li data-type="taskItem"[^>]*>)([\s\S]*?)(<\/li>)/gi, (match, openTag, liContent, closeTag) => {
                            // Support @YYYY-MM-DD or @YYYY-MM-DD HH:MM anywhere in the text
                            // and extract it so it becomes a native Tiptap attribute
                            const dateRegex = /@(\d{4}-\d{2}-\d{2}(?:\s+\d{2}:\d{2})?)/;
                            const dateMatch = liContent.match(dateRegex);
                            if (dateMatch) {
                                const dateStr = dateMatch[1];
                                // Normalise space to T for consistent data-date attribute
                                const isoDate = dateStr.replace(' ', 'T');
                                const cleanedContent = liContent.replace(dateRegex, '').trim();
                                return `${openTag.replace('>', ` data-date="${isoDate}" data-has-date="true" data-has-time="${isoDate.includes('T')}">`)}${cleanedContent}${closeTag}`;
                            }
                            return match;
                        });

                        const selection = editor.state.selection;
                        editor.commands.setContent(html, false);

                        if (isExternalUpdate) {
                            try {
                                editor.commands.setTextSelection(selection);
                            } catch (e) { /* ignore */ }
                        }
                    };
                    loadContent();
                }
            }
        }
    }, [fileId, nodes, editor, file?.id, syncPulse, getFileContent]);

    if (!file) return null;

    return (
        <div style={{ display: 'flex', flexDirection: 'column', height: '100%', position: 'relative', minHeight: 0 }}>
            <div className="editor-header-bar">
                <input
                    name="note-title"
                    id="note-title"
                    className="title-input"
                    value={localTitle}
                    onChange={handleTitleChange}
                    placeholder="Note Title"
                />
                <div style={{ display: 'flex', alignItems: 'center', marginLeft: 'auto', gap: '16px' }}>
                    <span style={{ color: 'var(--text-tertiary)', fontSize: '13px', whiteSpace: 'nowrap' }}>
                        {(() => {
                            if (!editor) return '0 words / 0 chars';
                            const textLength = editor.storage.characterCount?.characters() ?? editor.getText().length;
                            const text = editor.getText();
                            const words = text.trim() ? text.trim().split(/\s+/).length : 0;
                            return `${words} words / ${textLength} chars`;
                        })()}
                    </span>
                    <button
                        className="icon-button"
                        onClick={() => setTemplateMenu({ isOpen: true, selectedIndex: 0 })}
                        title="Insert Template (Insert key)"
                        style={{ color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '6px' }}
                    >
                        <LayoutTemplate size={18} />
                        <span style={{ fontSize: '13px', fontWeight: '500' }}>Template</span>
                    </button>
                    <button
                        className="icon-button"
                        onClick={() => setShowDeleteConfirm(true)}
                        title="Delete Note"
                        style={{ color: 'var(--danger-color)' }}
                    >
                        <Trash size={18} />
                    </button>
                </div>
            </div>

            {showDeleteConfirm && (
                <div className="modal-overlay" onClick={() => setShowDeleteConfirm(false)}>
                    <div className="modal-content" onClick={e => e.stopPropagation()}>
                        <h2 style={{ marginTop: 0, color: 'var(--text-primary)', fontSize: '20px', fontWeight: '600', marginBottom: '8px' }}>Delete Note</h2>
                        <p style={{ color: 'var(--text-secondary)', fontSize: '14.5px', marginBottom: '28px', lineHeight: '1.5' }}>
                            Are you sure you want to delete <strong style={{ color: 'var(--text-primary)' }}>"{localTitle || 'Untitled Note'}"</strong>?<br />This action cannot be undone.
                        </p>
                        <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
                            <button className="secondary-btn" onClick={() => setShowDeleteConfirm(false)} style={{ padding: '8px 16px', borderRadius: '6px', cursor: 'pointer', fontWeight: '500', border: '1px solid var(--border-color)', background: 'transparent', color: 'var(--text-primary)' }}>Cancel</button>
                            <button className="danger-btn" autoFocus onClick={() => { setShowDeleteConfirm(false); removeNode(fileId); }} style={{ padding: '8px 16px', borderRadius: '6px', background: 'var(--danger-color)', color: 'white', border: 'none', cursor: 'pointer', fontWeight: '500' }}>Delete Note</button>
                        </div>
                    </div>
                </div>
            )}

            <div className="editor-body" style={{ flex: 1, overflowY: 'auto', padding: '24px', position: 'relative' }} onKeyDownCapture={handleKeyDown}>
                <EditorContent editor={editor} className="tiptap-container" />
                <Backlinks noteId={fileId} />

                {/* Table Trigger Button and its Menu */}
                {tableTriggerCoords && (
                    <>
                        <button
                            className="table-trigger-btn"
                            style={{ position: 'fixed', top: tableTriggerCoords.top - 8, left: tableTriggerCoords.right - 28, zIndex: 105 }}
                            onClick={() => setIsTableMenuOpen(!isTableMenuOpen)}
                            title="Table Options"
                        >
                            <MoreHorizontal size={18} />
                        </button>
                        {isTableMenuOpen && <TableControlsMenu editor={editor} trigger={tableTriggerCoords} onClose={() => setIsTableMenuOpen(false)} />}
                    </>
                )}

                <TemplateModal
                    isOpen={isTemplateModalOpen}
                    onClose={() => setIsTemplateModalOpen(false)}
                    onInsertTemplate={handleInsertTemplate}
                    editorContent={lastSavedContentRef.current}
                />

                {/* Custom Bubble (Formatting) Menu */}
                {!editor.isActive('table') && <BubbleMenuUI editor={editor} bubbleMenu={bubbleMenu} setBubbleMenu={setBubbleMenu} />}

                {/* Custom Slash Menu */}
                {slashMenu.isOpen && (
                    <div style={{
                        position: 'fixed',
                        top: slashMenu.top,
                        left: slashMenu.left,
                        backgroundColor: 'var(--bg-secondary)',
                        border: '1px solid var(--border-color)',
                        borderRadius: '8px',
                        boxShadow: 'var(--shadow-md)',
                        zIndex: 1000,
                        minWidth: '200px',
                        padding: '4px',
                        maxHeight: '300px',
                        overflowY: 'auto'
                    }}>

                        <ul ref={slashMenuListRef} style={{ listStyle: 'none', margin: 0, padding: 0 }}>
                            {SLASH_OPTIONS.filter(o => o.label.toLowerCase().includes(slashMenu.query.toLowerCase())).map((opt, idx) => (
                                <li
                                    key={idx}
                                    onMouseDown={(e) => {
                                        e.preventDefault();
                                        editor.chain().focus().deleteRange({ from: slashMenu.triggerIdx, to: editor.state.selection.from }).run();
                                        opt.command(editor);
                                        setSlashMenu(prev => ({ ...prev, isOpen: false }));
                                    }}
                                    style={{
                                        padding: '8px 12px',
                                        cursor: 'pointer',
                                        borderRadius: '4px',
                                        backgroundColor: idx === slashMenu.selectedIndex ? 'var(--bg-accent)' : 'transparent',
                                        color: idx === slashMenu.selectedIndex ? 'var(--text-primary)' : 'var(--text-secondary)',
                                        fontSize: '14px',
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: '12px'
                                    }}
                                >
                                    <span style={{ fontSize: '12px', opacity: 0.6, width: '20px', textAlign: 'center' }}>{opt.icon}</span>
                                    {opt.label}
                                </li>
                            ))}
                        </ul>
                    </div>
                )}

                {/* Custom Tag Menu */}
                {tagMenu.isOpen && (
                    <div style={{
                        position: 'fixed',
                        top: tagMenu.top,
                        left: tagMenu.left,
                        backgroundColor: 'var(--bg-secondary)',
                        border: '1px solid var(--border-color)',
                        borderRadius: '8px',
                        boxShadow: 'var(--shadow-md)',
                        zIndex: 1000,
                        minWidth: '200px',
                        padding: '4px',
                        maxHeight: '200px',
                        overflowY: 'auto'
                    }}>
                        <ul ref={tagMenuListRef} style={{ listStyle: 'none', margin: 0, padding: 0 }}>
                            {availableTags.filter(tag => tag && tag.toLowerCase().includes((tagMenu.query || '').toLowerCase())).map((tag, idx) => (
                                <li
                                    key={idx}
                                    onMouseDown={(e) => {
                                        e.preventDefault();
                                        editor.chain().focus().deleteRange({ from: tagMenu.triggerIdx, to: editor.state.selection.from }).insertContent(`#${tag} `).run();
                                        setTagMenu(prev => ({ ...prev, isOpen: false }));
                                    }}
                                    style={{
                                        padding: '8px 12px',
                                        cursor: 'pointer',
                                        borderRadius: '4px',
                                        backgroundColor: idx === tagMenu.selectedIndex ? 'var(--bg-accent)' : 'transparent',
                                        color: idx === tagMenu.selectedIndex ? 'var(--accent-color)' : 'var(--text-primary)',
                                        fontSize: '14px',
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: '8px',
                                        fontWeight: 500
                                    }}
                                >
                                    <span style={{ color: 'var(--text-tertiary)' }}>#</span>
                                    {tag}
                                </li>
                            ))}
                            {availableTags.filter(tag => tag && tag.toLowerCase().includes((tagMenu.query || '').toLowerCase())).length === 0 && (
                                <li style={{ padding: '8px 12px', color: 'var(--text-tertiary)', fontSize: '13px', fontStyle: 'italic' }}>
                                    Keep typing to create new tag...
                                </li>
                            )}
                        </ul>
                    </div>
                )}

                {/* Custom Link Menu */}
                {linkMenu.isOpen && (
                    <div style={{
                        position: 'fixed',
                        top: linkMenu.top,
                        left: linkMenu.left,
                        backgroundColor: 'var(--bg-secondary)',
                        border: '1px solid var(--border-color)',
                        borderRadius: '8px',
                        boxShadow: 'var(--shadow-md)',
                        zIndex: 1000,
                        minWidth: '240px',
                        padding: '4px',
                        maxHeight: '250px',
                        overflowY: 'auto'
                    }}>
                        <ul ref={linkMenuListRef} style={{ listStyle: 'none', margin: 0, padding: 0 }}>
                            {nodes
                                .filter(n => n.type === 'file' && n.name.toLowerCase().includes((linkMenu.query || '').toLowerCase()))
                                .map((node, idx) => (
                                    <li
                                        key={node.id}
                                        onMouseDown={(e) => {
                                            e.preventDefault();
                                            editor.chain().focus().deleteRange({ from: linkMenu.triggerIdx, to: editor.state.selection.from }).insertContent(`[[${node.name}]] `).run();
                                            setLinkMenu(prev => ({ ...prev, isOpen: false }));
                                        }}
                                        style={{
                                            padding: '8px 12px',
                                            cursor: 'pointer',
                                            borderRadius: '4px',
                                            backgroundColor: idx === linkMenu.selectedIndex ? 'var(--bg-accent)' : 'transparent',
                                            color: idx === linkMenu.selectedIndex ? 'var(--accent-color)' : 'var(--text-primary)',
                                            fontSize: '14px',
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: '8px',
                                            fontWeight: 500
                                        }}
                                    >
                                        <span style={{ color: 'var(--text-tertiary)' }}>📄</span>
                                        {node.name}
                                    </li>
                                ))}
                            {nodes.filter(n => n.type === 'file' && n.name.toLowerCase().includes((linkMenu.query || '').toLowerCase())).length === 0 && (
                                <li style={{ padding: '8px 12px', color: 'var(--text-tertiary)', fontSize: '13px', fontStyle: 'italic' }}>
                                    Create link to "{linkMenu.query}"...
                                </li>
                            )}
                        </ul>
                    </div>
                )}
            </div>

            <style>{`
                .custom-bubble-menu {
                    display: flex;
                    background: var(--bg-secondary);
                    padding: 4px;
                    border-radius: 8px;
                    border: 1px solid var(--border-color);
                    box-shadow: var(--shadow-md);
                    gap: 2px;
                    backdrop-filter: blur(8px);
                }
                .custom-bubble-menu button {
                    background: transparent;
                    border: none;
                    border-radius: 4px;
                    padding: 6px;
                    color: var(--text-secondary);
                    cursor: pointer;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                }
                .custom-bubble-menu button.is-active {
                    background: var(--accent-color);
                    color: white;
                }
                .menu-separator {
                    width: 1px;
                    height: 20px;
                    background: var(--border-color);
                    align-self: center;
                    margin: 0 4px;
                }
                .table-controls-enhanced {
                    display: flex;
                    flex-direction: row;
                    padding: 8px;
                    gap: 12px;
                }
                .table-controls-group {
                    display: flex;
                    flex-direction: column;
                    gap: 4px;
                }
                .table-controls-group button {
                    justify-content: flex-start;
                    gap: 8px;
                    padding: 6px 12px;
                    width: 100%;
                    font-size: 13px;
                }
                .table-controls-group button:hover {
                    background: var(--bg-hover);
                }
                .menu-separator-vertical {
                    width: 1px;
                    background: var(--border-color);
                    align-self: stretch;
                }
                .custom-bubble-menu button.danger-btn {
                    color: var(--danger-color) !important;
                }
                .custom-bubble-menu button.danger-btn:hover {
                    background: rgba(239, 68, 68, 0.1) !important;
                }
                .title-input {
                    background: transparent;
                    border: none;
                    outline: none;
                    font-size: 24px;
                    font-weight: bold;
                    color: var(--text-primary);
                    width: 100%;
                }
                .tiptap-container {
                    user-select: text !important;
                    -webkit-user-select: text !important;
                    outline: none;
                }
                .editor-link {
                    color: var(--accent-color);
                    text-decoration: underline;
                    cursor: pointer;
                }
                .editor-link:hover {
                    opacity: 0.8;
                }
                .table-trigger-btn {
                    background: var(--bg-secondary);
                    border: 1px solid var(--border-color);
                    border-radius: 6px;
                    padding: 4px;
                    cursor: pointer;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    color: var(--text-secondary);
                    box-shadow: var(--shadow-sm);
                    transition: all 0.2s;
                }
                .table-trigger-btn:hover {
                    background: var(--bg-hover);
                    color: var(--text-primary);
                    border-color: var(--text-tertiary);
                }
                .editor-wikilink {
                    color: var(--accent-color);
                    background-color: var(--bg-accent);
                    padding: 2px 6px;
                    border-radius: 4px;
                    font-size: 0.95em;
                    cursor: pointer;
                    transition: opacity 0.2s;
                    text-decoration: none;
                }
                .editor-wikilink:hover {
                    opacity: 0.8;
                }
            `}</style>
        </div >
    );
}
